		// Registered max-tier animation styles. Each entry declares:
		//   id        — persisted in settingsScope.effortStyle
		//   titleKey  — locale key used by the settings dropdown
		//   kind      — "fill": renders INSIDE the bar fill, gated through
		//               .dms-fillMax.dms-fx-<id> classes (spray-flow);
		//               "overlay": renders as a bar-covering layer with its
		//               own entry/exit choreography (undertow).
		// Adding the next style = append an entry here + locale key
		// "style.<id>" + a render branch in ModelEffortControl (see the
		// ADDING_A_STYLE checklist there) + its CSS classes. The settings
		// dropdown and the stored-value whitelist pick entries up
		// automatically.
		const EFFECT_STYLES = [
			{ id: "spray-flow", titleKey: "style.sprayFlow", kind: "fill" },
			{ id: "undertow", titleKey: "style.undertow", kind: "overlay" },
			{ id: "cosmos", titleKey: "style.cosmos", kind: "fill" },
			{ id: "sunset", titleKey: "style.sunset", kind: "fill" }
		];
		const DEFAULT_STYLE = "spray-flow";
		const styleById = function (id) {
			for (let i = 0; i < EFFECT_STYLES.length; i++) {
				if (EFFECT_STYLES[i].id === id) return EFFECT_STYLES[i];
			}
			return null;
		};

		// Frosted-glass defaults (matching the original fixed glass look):
		// opacity in %, blur radius in px.
		const DEFAULT_GLASS_OPACITY = 62;
		const DEFAULT_GLASS_BLUR = 16;
		const GLASS_OPACITY_MIN = 20;
		// NOT 100. The panel's glass background is
		// `color-mix(in srgb, <menu token> var(--dms-glass-op), transparent)`, so at
		// 100% that expression evaluates to the menu token ITSELF — byte-identical to
		// what the panel paints with glass OFF — and the backdrop-filter has nothing
		// left to blur, because there is no longer anything showing through. Rendering
		// the two states side by side confirms they are visually identical.
		//
		// That made the whole feature look broken at the top of the slider's range:
		// "toggling the glass does nothing" and "the blur does nothing" are both the
		// correct observation at 100%, and a saved 100% therefore outlives the
		// session as a config that silently defeats its own setting. Capping below
		// 100 keeps "glass ON" always visibly translucent, which is what makes the
		// toggle and the blur parameter mean something at EVERY slider position.
