		// delay and random mid-left fade-out point.
		const RUNNERS = (function () {
			const list = [];
			for (let k = 0; k < 100; k++) {
				list.push({
					y: 10 + Math.random() * 80,
					from: 88 + Math.random() * 10,
					to: 24 + Math.random() * 14,
					dur: 1.1 + Math.random() * 0.9,
					delay: Math.random() * 1.2
				});
			}
			return list;
		})();

