			".dms-fillSheen{position:absolute;inset:0;border-radius:10px;background:linear-gradient(110deg,#1D4ED8,#2563EB 30%,#4F46E5 55%,#7C3AED 80%,#A855F7);background-size:250% 100%;opacity:0;box-shadow:inset 0 1px 1px rgba(255,255,255,.35);transition:opacity .5s cubic-bezier(.4,0,.2,1)}",
			".dms-fillMax.dms-fx-spray-flow .dms-fillSheen{opacity:1;animation:dms-sheen 5s ease-in-out infinite}",
			".dms-fillGlint{position:absolute;inset:0;border-radius:10px;background:linear-gradient(105deg,transparent 42%,rgba(255,255,255,.38) 50%,transparent 58%);background-size:220% 100%;opacity:0;transition:opacity .5s cubic-bezier(.4,0,.2,1);pointer-events:none}",
			".dms-fillMax.dms-fx-spray-flow .dms-fillGlint{opacity:1;animation:dms-glint 3.6s ease-in-out infinite}",
			// The two multi-child effect layers (spray particles, and the undertow
