			".dms-fillSpray{contain:layout paint;position:absolute;inset:0;border-radius:10px;overflow:hidden;opacity:0;transition:opacity .5s cubic-bezier(.4,0,.2,1);pointer-events:none}",
			".dms-fillMax.dms-fx-spray-flow .dms-fillSpray{opacity:1}",
			".dms-sprayCore{position:absolute;top:0;bottom:0;right:0;width:72%;border-radius:10px;background:linear-gradient(270deg,rgba(255,255,255,.38) 0%,rgba(255,255,255,.16) 28%,rgba(255,255,255,.05) 55%,rgba(255,255,255,0) 100%);filter:blur(2.5px);opacity:0;transition:opacity .5s cubic-bezier(.4,0,.2,1);pointer-events:none;transform-origin:right center}",
			".dms-fillMax.dms-fx-spray-flow .dms-sprayCore{opacity:1;animation:dms-corebreath 1.6s ease-in-out infinite}",
			".dms-sprayNozzle{position:absolute;top:50%;right:0;width:30px;height:24px;margin-top:-12px;border-radius:50%;background:radial-gradient(ellipse at center,rgba(255,255,255,.7) 0%,rgba(255,255,255,.3) 45%,rgba(255,255,255,0) 72%);filter:blur(1px);opacity:0;pointer-events:none}",
			".dms-fillMax.dms-fx-spray-flow .dms-sprayNozzle{opacity:1;animation:dms-nozzle 1.6s ease-in-out infinite}",
			".dms-sprayWrap{position:absolute;inset:0;opacity:0;animation:dms-ignite .55s ease-out var(--launch,0s) both;pointer-events:none}",
			".dms-sprayDot{position:absolute;left:var(--x,95%);top:var(--y,50%);width:calc(var(--s,3px) * var(--tl,3));height:var(--s,3px);margin-top:calc(var(--s,3px) / -2);border-radius:50%;background:linear-gradient(90deg,rgba(255,255,255,1) 0%,rgba(255,255,255,.55) 30%,rgba(255,255,255,0) 100%);filter:drop-shadow(0 0 2px rgba(255,255,255,.75));opacity:0;animation:dms-spray var(--dur,1.5s) linear var(--delay,0s) infinite}",
			// Cosmos fluid style: a LIGHT body of liquid with soft blue ink
			// patches wandering through it — near-white ground, pale/mid/deep
			// blue blobs, all blurred into cloud-like wisps (参考图: 不规律运动的流体).
			// NO stripes, NO spark dots, and NO one-way current any more.
			".dms-fillMax.dms-fx-cosmos{background-color:#e9f1fd}",
			".dms-fillCosmos{contain:layout paint;position:absolute;inset:0;border-radius:10px;overflow:hidden;opacity:0;transition:opacity .5s cubic-bezier(.4,0,.2,1);pointer-events:none}",
			".dms-fillMax.dms-fx-cosmos .dms-fillCosmos{opacity:1}",
			// IRREGULAR MOTION ("不规律运动"): every layer runs its own CLOSED
			// transform loop forever, and the loops differ in everything that
			// matters — stop positions (23/47/71 vs 19/44/68/87 vs 29/57/82),
			// durations (17s / 13s / 9s, incommensurate) and translate/scale
			// deltas — so the three blob fields drift through one another and
			// the superposition never visibly repeats. `ease-in-out` lets each
			// leg swell and settle like a liquid; a constant-speed `linear`
			// march is exactly what this style replaced. Each loop CLOSES (the
			// 100% stop restates 0% exactly), so the wrap is invisible without
			// needing a tiling background.
			//
			// The blobs are radial "ink patches" whose vertical radius (130–180px)
			// dwarfs the 24–28px bar and whose centre sits at 50%: colour does
			// not fade before reaching the top/bottom edges, so patches read as
			// full-height fluid, never as horizontal strata (ui: "颜色不要分上中下").
			// Horizontal oversize (-25% both sides) plus the container's
			// overflow:hidden keep the wandering translate from exposing an edge.
			//
			// Base: two huge pale washes — the lightest, slowest body of water.
			".dms-cosmosFluidBase{position:absolute;top:0;bottom:0;left:-25%;right:-25%;filter:blur(9px);background:radial-gradient(ellipse 140px 160px at 24% 50%,rgba(191,216,250,.95) 0%,rgba(191,216,250,.55) 45%,transparent 75%),radial-gradient(ellipse 160px 180px at 70% 50%,rgba(216,232,253,.9) 0%,rgba(216,232,253,.5) 42%,transparent 72%);animation:dms-fluid-wander-a 17s ease-in-out infinite}",
			// Mid: the dominant medium-blue patches, three of them so the bar
			// never reads as symmetric.
			".dms-cosmosFluidMid{position:absolute;top:0;bottom:0;left:-25%;right:-25%;filter:blur(8px);background:radial-gradient(ellipse 95px 160px at 15% 50%,rgba(128,168,241,.9) 0%,rgba(128,168,241,.5) 45%,transparent 74%),radial-gradient(ellipse 110px 170px at 56% 50%,rgba(91,135,233,.85) 0%,rgba(91,135,233,.48) 42%,transparent 72%),radial-gradient(ellipse 80px 150px at 87% 50%,rgba(157,189,247,.85) 0%,rgba(157,189,247,.45) 40%,transparent 70%);animation:dms-fluid-wander-b 13s ease-in-out infinite}",
			// Top: the deepest accents plus ONE WHITE WISP that carves a bright
			// gap back out of the blue — the reference image is mostly white
			// with blue patches, so the highlights matter as much as the ink.
			".dms-cosmosFluidTop{position:absolute;top:0;bottom:0;left:-25%;right:-25%;filter:blur(6px);background:radial-gradient(ellipse 70px 140px at 31% 50%,rgba(63,111,215,.8) 0%,rgba(63,111,215,.45) 42%,transparent 70%),radial-gradient(ellipse 85px 150px at 75% 50%,rgba(85,131,227,.75) 0%,rgba(85,131,227,.4) 40%,transparent 68%),radial-gradient(ellipse 65px 130px at 53% 50%,rgba(255,255,255,.9) 0%,rgba(255,255,255,.5) 38%,transparent 66%);animation:dms-fluid-wander-c 9s ease-in-out infinite}",
			// Deliberately NO one-shot entry layer here. The effect is pure
			// continuous flow: the three layers above never start or stop, they
			// are simply revealed by `.dms-fillCosmos`'s own 0.5s opacity fade
